<template>
  <main class="ppt-studio">
    <nav class="studio-nav"><button class="brand" @click="router.push('/dashboard')"><i>D</i><span><b>Dokiai Academic</b><small>AI PRESENTATION STUDIO</small></span></button><div><span>Academic AI</span><button @click="router.push('/dashboard')">返回工作台</button></div></nav>
    <header class="hero"><div class="eyebrow"><i></i>DOKIAI PPT WORKFLOW</div><h1>让论文自动变成<br><em>专业答辩 PPT</em></h1><p>AI 理解论文结构，提炼答辩逻辑，自动生成可编辑 PPTX。</p><div class="hero-actions"><button class="primary" @click="scrollToUpload">开始生成 PPT　→</button><button class="secondary" @click="showFlow=!showFlow">查看生成流程　⌄</button></div><div class="support"><span>支持格式</span><b>PPTX</b><b>DOCX</b><b>PDF</b></div><i class="orb one"></i><i class="orb two"></i></header>

    <section v-if="stage==='upload'" ref="uploadSection" class="start-grid">
      <article class="glass upload-card"><header><div><small>STEP 01 · SOURCE FILE</small><h2>上传完整源文件</h2></div><span class="chip">AI READY</span></header><label class="drop-zone" :class="{selected:file}" @dragover.prevent @drop.prevent="onDrop"><input type="file" accept=".pptx,.docx,.pdf" @change="selectFile"><span class="upload-icon">↑</span><template v-if="!file"><strong>拖入论文或项目文档</strong><p>或点击选择本地文件 · 最大 80 MB</p><div><b>PPTX</b><b>DOCX</b><b>PDF</b></div></template><template v-else><span class="file-type">{{ fileExt }}</span><strong>{{ file.name }}</strong><p>{{ formatBytes(file.size) }} · 已准备解析</p><button type="button" @click.prevent="file=null">重新选择</button></template></label><div class="recognition"><span>AI 自动识别</span><ul><li>✓ 章节结构</li><li>✓ 图片素材</li><li>✓ 表格数据</li><li>✓ 答辩重点</li></ul></div></article>
      <article class="glass info-card"><header><div><small>PROJECT PROFILE</small><h2>项目资料确认</h2></div><button class="detect" :disabled="!file" @click="autoHint">✦ AI 自动识别</button></header><div class="detect-state"><i>✦</i><span><b>{{ file?'文档已就绪':'等待 AI 读取' }}</b><small>{{ file?'上传后将自动提取题目、作者与专业信息':'选择完整文档后自动识别，无需逐项填写' }}</small></span></div><div class="form-grid"><label class="wide"><span>论文题目 <small>AI 可识别</small></span><input v-model="form.topic" placeholder="上传后自动提取"></label><label><span>汇报人</span><input v-model="form.presenter" placeholder="AI 自动提取"></label><label><span>专业</span><input v-model="form.major" placeholder="AI 自动提取"></label><label><span>指导教师</span><input v-model="form.advisor" placeholder="AI 自动提取"></label><label><span>学号</span><input v-model="form.studentNumber" placeholder="AI 自动提取"></label></div></article>
      <article class="glass template-card"><header><div><small>RENDERING V1 TEMPLATE</small><h2>选择答辩视觉模板</h2></div><button class="detect" :class="{active:selectedTemplateId==='AI_RECOMMEND'}" @click="useAiRecommendation">✦ 交给 AI 推荐</button></header><p class="template-hint">仅展示已审计并编译为可信 TemplatePack 的模板；选择会在页面规划前冻结，生成阶段不会临时换模板。</p><div class="template-grid"><button v-for="option in supportedTemplates" :key="option.templatePackId" type="button" class="template-option" :class="{selected:selectedTemplateId===option.templatePackId}" @click="selectedTemplateId=option.templatePackId"><span class="template-preview" :class="option.templatePackId"></span><span><b>{{ option.templateName }}</b><small>{{ option.description }}</small><em>{{ option.templatePackId==='small-bear-watercolor-blue-v1'?'小熊熊系列 · 本次推荐':'稳定学术基线' }}</em></span><i>{{ selectedTemplateId===option.templatePackId?'✓':'选择' }}</i></button></div><footer><span v-if="selectedTemplateId==='AI_RECOMMEND'">✦ AI 将在解析论文后，根据文档类型和图片比例推荐可信模板。</span><span v-else>✓ 将使用：{{ selectedTemplateName }}</span></footer><button class="generate" :disabled="!file||busy" @click="start"><span>✦</span>{{ busy?'AI 正在启动工作流':'开始智能生成' }}<b>→</b></button><p class="safe-note">文档仅用于本次内容分析与 PPT 生成</p></article>
    </section>

    <section v-else class="workflow-center">
      <article class="glass task-card" :class="{failed:stage==='error',complete:stage==='done'}"><div class="task-icon"><span v-if="stage==='done'">✓</span><span v-else-if="stage==='error'">!</span><i v-else></i></div><div><small>{{ stage==='done'?'GENERATION COMPLETE':stage==='error'?'TASK INTERRUPTED':'AI IS WORKING' }}</small><h2>{{ taskTitle }}</h2><p>{{ taskDescription }}</p></div><strong>{{ displayProgress }}<small>%</small></strong><div class="master-progress"><i :style="{width:displayProgress+'%'}"></i></div><footer><span>当前步骤：<b>{{ activeStepLabel }}</b></span><span>当前页面：<b>{{ currentPage }}/{{ totalPages }}</b></span><span>任务 ID：<b>{{ shortId }}</b></span></footer></article>
      <article class="glass flow-card"><header><div><small>LIVE WORKFLOW</small><h2>AI PPT 生成流程</h2></div><span>{{ completedStepCount }}/6 已完成</span></header><div class="steps"><div v-for="item in workflowSteps" :key="item.no" :class="item.state"><span><i v-if="item.state==='done'">✓</i><b v-else>{{ item.no }}</b></span><div><small>STEP {{ item.no }}</small><strong>{{ item.title }}</strong><p>{{ item.description }}</p></div><em>{{ stateLabel(item.state) }}</em></div></div></article>
      <div class="workflow-grid"><article class="glass analysis-card"><header><div><small>DOCUMENT INSIGHTS</small><h2>文档识别结果</h2></div><span class="success-dot">识别完成</span></header><div class="metrics"><span><i>章</i><b>{{ analysis.precheck?.validChapterCount||analysis.headings?.length||0 }}</b><small>有效章节</small></span><span><i>图</i><b>{{ analysis.validImageCount||analysis.imageCount||0 }}</b><small>有效图片</small></span><span><i>表</i><b>{{ analysis.tableCount||0 }}</b><small>数据表格</small></span></div><p>{{ analysis.precheck?.message||'AI 正在建立论文内容索引' }}</p></article><article class="glass log-card"><header><div><small>PROCESS LOG</small><h2>生成过程日志</h2></div><button @click="logsOpen=!logsOpen">{{ logsOpen?'收起':'展开全部' }}⌄</button></header><ul><li v-for="(log,i) in visibleLogs" :key="i"><i :class="log.type">{{ log.type==='doing'?'↻':log.type==='error'?'!':'✓' }}</i><span>{{ log.text }}</span><time>{{ log.time }}</time></li></ul></article></div>
      <article v-if="stage==='done'" class="glass result-card"><div class="result-mark">✓</div><div><small>PRESENTATION READY</small><h2>基础版 PPT 生成完成</h2><p>文字、图片和表格均保持独立可编辑，基础文件会永久保留。</p></div><div class="result-stats"><span><b>{{ totalPages }}</b>页</span><span><b>{{ resultSize }}</b>文件大小</span><span><b>{{ elapsedText }}</b>生成耗时</span></div><div class="result-actions"><button class="secondary" @click="preview">预览基础版</button><button class="primary" @click="download">下载基础版 ↓</button><button class="text-button" @click="reset">重新生成</button></div></article>
      <article v-if="stage==='done'" class="glass enhancement-card" :class="enhancementStateClass"><div class="enhancement-mark"><span v-if="enhancementStatus==='SUCCESS'">✓</span><i v-else-if="enhancementRunning"></i><span v-else-if="enhancementStatus==='FAILED'">!</span><span v-else>✦</span></div><div class="enhancement-copy"><small>AI PRESENTATION ENHANCEMENT</small><h2>{{ enhancementTitle }}</h2><p>{{ enhancementDescription }}</p><div class="enhancement-provider" :class="enhancementProviderState"><b>{{ enhancementProviderName }}</b><span>{{ enhancementProviderInvocation }}</span><em>{{ enhancementProviderStatus }}</em></div><div v-if="enhancementRunning" class="enhancement-progress"><span><i :style="{width:enhancementProgress+'%'}"></i></span><b>{{ enhancementProgress }}%</b></div><div v-if="enhancementStatus==='FAILED'" class="enhancement-error"><b>失败步骤：{{ enhancementStageLabel }}</b><span>{{ enhancementTask.errorMessage||'增强任务未完成，基础版 PPT 不受影响且不会扣除积分。' }}</span></div><div v-if="enhancementStatus==='SUCCESS'" class="enhancement-meta"><span><b>{{ enhancementTask.slideCount||totalPages }}</b>页</span><span><b>{{ enhancementSize }}</b>增强版大小</span><span><b>{{ enhancementChargedPoints }}</b>积分已扣除</span></div></div><aside v-if="enhancementStatus==='IDLE'" class="enhancement-price"><small>本次增幅费用</small><strong>{{ enhancementCost }}<em>积分</em></strong><span>基础生成费用的 50%</span><span v-if="enhancementQuote.currentPoints!=null">当前余额 {{ enhancementQuote.currentPoints }} 积分</span></aside><div class="enhancement-actions"><template v-if="enhancementStatus==='SUCCESS'"><button class="secondary" :disabled="!enhancementDownloadable" @click="previewEnhancement">预览增强版</button><button class="primary" :disabled="!enhancementDownloadable" @click="downloadEnhancementFile">下载增强版 ↓</button><button class="text-button" :disabled="enhancementBusy" @click="confirmEnhancement">重新增强</button><span v-if="!enhancementDownloadable">增强文件尚未通过下载校验，请稍后刷新任务状态</span></template><template v-else-if="enhancementStatus==='FAILED'"><button class="primary" :disabled="enhancementStartDisabled" @click="confirmEnhancement">重新增强</button><span>{{ enhancementAvailabilityHint }}</span></template><template v-else-if="enhancementRunning"><button class="secondary" disabled>AI 增幅处理中</button><span>可继续下载上方基础版</span></template><template v-else><button class="enhance-button" :disabled="enhancementStartDisabled" @click="confirmEnhancement"><span>✦</span>{{ enhancementStartLabel }}<b>→</b></button><span>{{ enhancementAvailabilityHint }}</span></template></div></article>
      <article v-if="stage==='error'" class="glass error-card"><span>!</span><div><small>AI TASK EXCEPTION</small><h2>任务在「{{ activeStepLabel }}」阶段中断</h2><p>{{ errorMessage }}</p></div><button class="secondary" @click="resume">重新执行当前步骤</button><button class="primary" @click="reset">重新生成</button></article>
    </section>
    <section v-if="showFlow&&stage==='upload'" class="flow-preview glass"><small>HOW IT WORKS</small><h2>从论文到答辩 PPT，只需一次上传</h2><div><span v-for="item in workflowSteps" :key="item.no"><b>{{ item.no }}</b><strong>{{ item.title }}</strong><small>{{ item.description }}</small></span></div></section>
  </main>
</template>

<script setup>
import { computed,onBeforeUnmount,onMounted,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { ElMessage,ElMessageBox } from 'element-plus';import { createPptProject,getPptProject,uploadPptSource,analyzePptProject,generatePptOutline,savePptOutline,planPptSlides,generatePptFile,getPptProgress,downloadPptFile,getPptEnhancementQuote,startPptEnhancement,getPptEnhancementTask,downloadPptEnhancement,listPptTemplates,recommendPptTemplate,selectPptTemplate } from '../../api/rewrite';
const router=useRouter(),route=useRoute(),uploadSection=ref(null),stage=ref('upload'),busy=ref(false),file=ref(null),project=ref({progress:0}),analysis=ref({}),outline=ref([]),pages=ref([]),activeStep=ref(0),logs=ref([]),logsOpen=ref(false),showFlow=ref(false),errorMessage=ref(''),startedAt=ref(0),elapsed=ref(0),resultBytes=ref(0),generatedSlideCount=ref(0),templates=ref([]),selectedTemplateId=ref('AI_RECOMMEND'),enhancementQuote=ref({}),enhancementTask=ref({status:'IDLE',progress:0}),enhancementBusy=ref(false),enhancementPolling=ref(0),componentAlive=ref(true);const form=ref({topic:'',presenter:'',major:'',advisor:'',studentNumber:'',targetSlideCount:16});const stepData=[['01','文件解析','正在读取章节结构和文档内容'],['02','内容理解','AI 正在提炼答辩重点'],['03','页面规划','生成 PPT 页面结构'],['04','素材绑定','匹配图片和表格资源'],['05','智能排版','生成页面布局'],['06','PPT 生成','正在输出可编辑 PPTX']];
const workflowSteps=computed(()=>stepData.map((x,i)=>({no:x[0],title:x[1],description:x[2],state:stage.value==='done'||i<activeStep.value?'done':stage.value==='error'&&i===activeStep.value?'error':i===activeStep.value?'active':'waiting'})));
const cleanTopic=computed(()=>String(project.value.topic||form.value.topic||'未命名学术答辩').replace(/[\\/:*?"<>|]/g,'_'));
const fileExt=computed(()=>file.value?.name.split('.').pop()?.toUpperCase()||'FILE');
const displayProgress=computed(()=>stage.value==='done'?100:stage.value==='error'?Number(project.value.progress||activeStep.value*16):Math.max(Number(project.value.progress||0),Math.min(95,activeStep.value*16+8)));
const totalPages=computed(()=>Math.max(1,Number(generatedSlideCount.value||project.value.slideCount||project.value.slide_count||0)||pages.value.length||1));
const completedPages=computed(()=>pages.value.filter(x=>x.status==='SUCCESS').length);
const currentPage=computed(()=>stage.value==='done'?totalPages.value:Math.min(totalPages.value,Math.max(1,completedPages.value+1)));
const completedStepCount=computed(()=>workflowSteps.value.filter(x=>x.state==='done').length);
const activeStepLabel=computed(()=>stepData[Math.min(activeStep.value,5)][1]);
const shortId=computed(()=>String(project.value.id||'PREPARING').slice(0,8).toUpperCase());
const taskTitle=computed(()=>stage.value==='done'?'你的答辩 PPT 已准备好':stage.value==='error'?'AI 任务需要处理':`正在进行${activeStepLabel.value}`);
const taskDescription=computed(()=>stage.value==='done'?'已完成内容规划、素材绑定与可编辑 PPTX 输出。':stage.value==='error'?errorMessage.value:stepData[Math.min(activeStep.value,5)][2]);
const visibleLogs=computed(()=>logsOpen.value?logs.value:logs.value.slice(-3));
const resultSize=computed(()=>resultBytes.value?formatBytes(resultBytes.value):'生成完成');
const elapsedText=computed(()=>elapsed.value?`${(elapsed.value/1000).toFixed(1)}秒`:'已完成');
const enhancementStatus=computed(()=>String(enhancementTask.value.status||'IDLE').toUpperCase());
const enhancementRunning=computed(()=>['QUEUED','RUNNING','FINALIZING'].includes(enhancementStatus.value));
const enhancementProgress=computed(()=>Math.max(0,Math.min(100,Number(enhancementTask.value.progress||0))));
const enhancementCost=computed(()=>Number(enhancementQuote.value.costPoints??enhancementTask.value.costPoints??0));
const enhancementChargedPoints=computed(()=>typeof enhancementTask.value.pointsCharged==='number'?enhancementTask.value.pointsCharged:enhancementTask.value.pointsCharged?enhancementCost.value:0);
const enhancementDownloadable=computed(()=>enhancementStatus.value==='SUCCESS'&&enhancementTask.value.downloadable===true);
const enhancementProviderName=computed(()=>enhancementTask.value.provider==='doubao_ark'?'豆包 · 火山方舟':enhancementTask.value.provider||'豆包 · 火山方舟');
const enhancementProviderInvocation=computed(()=>enhancementTask.value.id?(enhancementTask.value.providerInvoked?'已真实调用':'等待调用'):enhancementQuote.value.providerConfigured===true?'服务已配置':enhancementQuote.value.providerConfigured===false?'服务未配置':'正在检查服务');
const enhancementProviderStatus=computed(()=>enhancementTask.value.providerStatus||(enhancementQuote.value.enabled===false?'DISABLED':enhancementQuote.value.providerConfigured===true?'READY':enhancementQuote.value.providerConfigured===false?'NOT_CONFIGURED':'CHECKING'));
const enhancementProviderState=computed(()=>enhancementProviderStatus.value==='SUCCESS'?'success':['FAILED','NOT_CONFIGURED','DISABLED'].includes(enhancementProviderStatus.value)?'failed':'active');
const enhancementStartDisabled=computed(()=>enhancementBusy.value||!enhancementQuote.value.baseGenerationTaskId||enhancementQuote.value.enabled===false||enhancementQuote.value.providerConfigured===false);
const enhancementStartLabel=computed(()=>enhancementBusy.value?'正在确认':enhancementQuote.value.enabled===false||enhancementQuote.value.providerConfigured===false?'增幅服务不可用':enhancementQuote.value.canStart===false?'积分不足 · 查看充值':'启动增幅美化');
const enhancementAvailabilityHint=computed(()=>enhancementQuote.value.enabled===false?'增幅美化功能当前未启用':enhancementQuote.value.providerConfigured===false?'豆包增幅服务尚未配置':enhancementQuote.value.canStart===false?`当前积分不足，还需 ${Math.max(0,enhancementCost.value-Number(enhancementQuote.value.currentPoints||0))} 积分`:'失败不扣积分 · 不覆盖基础文件');
const enhancementStageLabel=computed(()=>enhancementTask.value.currentStage||'增幅美化');
const enhancementSize=computed(()=>enhancementTask.value.fileSize?formatBytes(Number(enhancementTask.value.fileSize)):'已生成');
const enhancementStateClass=computed(()=>({running:enhancementRunning.value,success:enhancementStatus.value==='SUCCESS',failed:enhancementStatus.value==='FAILED'}));
const enhancementTitle=computed(()=>enhancementStatus.value==='SUCCESS'?'精美增强版已生成':enhancementStatus.value==='FAILED'?'增幅美化未完成':enhancementRunning.value?'AI 正在增幅美化':'让这份 PPT 再提升一个层级');
const enhancementDescription=computed(()=>enhancementStatus.value==='SUCCESS'?'增强版作为独立文件保存，基础版内容与下载入口均未改变。':enhancementStatus.value==='FAILED'?'本次未扣除积分，基础版 PPT 仍可正常使用。':enhancementRunning.value?`${enhancementStageLabel.value} · 完成后才会扣除积分`:'调用 PPT 增幅美化 Skill，在保持原文与模板身份的前提下强化视觉层级和页面精致度。');
const supportedTemplates=computed(()=>templates.value.filter(x=>x.renderingV1Supported&&['academic-purple','small-bear-watercolor-blue-v1'].includes(x.templatePackId))),selectedTemplateName=computed(()=>supportedTemplates.value.find(x=>x.templatePackId===selectedTemplateId.value)?.templateName||selectedTemplateId.value);
function formatBytes(n){return n>1048576?(n/1048576).toFixed(2)+' MB':Math.max(1,n/1024).toFixed(1)+' KB'}function stateLabel(v){return({done:'完成',active:'处理中',waiting:'等待',error:'异常'})[v]}function now(){return new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}function addLog(text,type='done'){logs.value.push({text,type,time:now()})}function nextStep(index,text){activeStep.value=index;addLog(text,index===5?'doing':'done')}function scrollToUpload(){uploadSection.value?.scrollIntoView({behavior:'smooth',block:'center'})}function selectFile(e){file.value=e.target.files?.[0]||null}function onDrop(e){file.value=e.dataTransfer.files?.[0]||null}function autoHint(){ElMessage.success('上传后将自动识别并回填项目信息')}function useAiRecommendation(){selectedTemplateId.value='AI_RECOMMEND';ElMessage.success('AI 将在内容解析后推荐并冻结可信模板')}function tick(){return new Promise(r=>setTimeout(r,120))}
async function loadTemplates(){try{templates.value=await listPptTemplates()}catch{templates.value=[{templatePackId:'academic-purple',templateName:'Academic Purple',description:'稳定学术基线',renderingV1Supported:true},{templatePackId:'small-bear-watercolor-blue-v1',templateName:'小熊熊·水彩蓝',description:'可信水彩蓝论文答辩模板',renderingV1Supported:true}]}}
async function freezeSelectedTemplate(){let templatePackId=selectedTemplateId.value;if(templatePackId==='AI_RECOMMEND'){const recommendation=await recommendPptTemplate(project.value.id);templatePackId=recommendation.templatePackId}const selected=await selectPptTemplate(project.value.id,{templatePackId});selectedTemplateId.value=selected.templatePackId;return selected}
function applyBaseGenerationResult(data={}){generatedSlideCount.value=Number(data.slideCount??data.slide_count??generatedSlideCount.value??0);resultBytes.value=Number(data.writtenBytes??data.written_bytes??data.fileSize??data.file_size??resultBytes.value??0)}
async function start(){busy.value=true;stage.value='running';startedAt.value=Date.now();logs.value=[];errorMessage.value='';resetEnhancement();try{nextStep(0,'正在上传并读取完整源文件');project.value=await createPptProject(form.value);project.value=await uploadPptSource(project.value.id,file.value);project.value=await analyzePptProject(project.value.id);analysis.value=JSON.parse(project.value.analysis_json||'{}');Object.assign(form.value,{topic:project.value.topic||form.value.topic,presenter:project.value.presenter||form.value.presenter,major:project.value.major||form.value.major,advisor:project.value.advisor||form.value.advisor,studentNumber:project.value.student_number||form.value.studentNumber});addLog(`已解析 ${analysis.value.precheck?.validChapterCount||analysis.value.headings?.length||0} 个章节`);nextStep(1,'AI 正在提炼答辩重点');const out=await generatePptOutline(project.value.id);project.value=out;outline.value=out.outline||[];addLog('已完成答辩内容理解');nextStep(2,'正在生成 PPT 页面结构');await saveOutlineOnly(false);const selected=await freezeSelectedTemplate();addLog(`已冻结可信模板：${selected.profile?.displayName||selected.profile?.templateName||selected.templatePackId}`);const planned=await planPptSlides(project.value.id);project.value=planned;pages.value=planned.slides||[];applyBaseGenerationResult(planned);addLog('PPT 页面结构已规划并冻结');nextStep(3,'正在匹配图片和表格资源');addLog(`已识别 ${analysis.value.validImageCount||analysis.value.imageCount||0} 张有效图片`);await tick();nextStep(4,'正在生成页面布局');await tick();nextStep(5,'正在输出可编辑 PPTX');applyBaseGenerationResult(await generatePptFile(project.value.id));await pollGeneration();elapsed.value=Date.now()-startedAt.value;addLog('可编辑 PPTX 已生成');stage.value='done';await loadEnhancementState()}catch(e){errorMessage.value=e?.responseData?.message||e.message||'生成任务暂时中断';addLog(errorMessage.value,'error');stage.value='error'}finally{busy.value=false}}
async function pollGeneration(){for(let attempt=0;attempt<600;attempt++){project.value=await getPptProgress(project.value.id);applyBaseGenerationResult(project.value);pages.value=project.value.slides||pages.value;const status=String(project.value.status||'');if(status==='SUCCESS')return project.value;if(status==='FAILED')throw new Error(project.value.error_message||'PPT生成失败');await new Promise(r=>setTimeout(r,1000))}throw new Error('PPT生成仍在进行，请稍后从当前项目继续')}
async function resumeCurrentProject(){if(!project.value.id){reset();return}busy.value=true;stage.value='running';startedAt.value=Date.now();errorMessage.value='';try{let status=String(project.value.status||'');if(status==='UPLOADED'){nextStep(0,'继续解析已上传文档');project.value=await analyzePptProject(project.value.id);status=String(project.value.status||'')}if(status==='ANALYZED'){nextStep(1,'继续生成答辩内容');const out=await generatePptOutline(project.value.id);project.value=out;outline.value=out.outline||[];await saveOutlineOnly(false);status=String(project.value.status||'')}if(status==='OUTLINE_READY'){nextStep(2,'继续生成页面规划');if(selectedTemplateId.value==='AI_RECOMMEND')await freezeSelectedTemplate();project.value=await planPptSlides(project.value.id);pages.value=project.value.slides||[];status=String(project.value.status||'')}if(status==='PLANNED'||status==='FAILED'){nextStep(5,'继续输出可编辑 PPTX');applyBaseGenerationResult(await generatePptFile(project.value.id));status='GENERATING'}if(status==='GENERATING')await pollGeneration();else if(status==='SUCCESS'){project.value=await getPptProgress(project.value.id);applyBaseGenerationResult(project.value)}else throw new Error('当前项目尚未完成文件上传，无法从此步骤继续');elapsed.value=Date.now()-startedAt.value;addLog('已从保存进度恢复并完成生成');stage.value='done';await loadEnhancementState()}catch(e){errorMessage.value=e?.responseData?.message||e.message||'恢复任务失败';addLog(errorMessage.value,'error');stage.value='error'}finally{busy.value=false}}
async function saveOutlineOnly(notify=true){const data=await savePptOutline(project.value.id,outline.value.map((x,i)=>({id:x.id,title:x.title,description:x.description||'',targetSlides:Math.min(2,Math.max(1,x.target_slides||1)),sectionOrder:i+1})));outline.value=data.outline||outline.value;if(notify)ElMessage.success('页面规划已保存')}async function getBlob(){const blob=await downloadPptFile(project.value.id);resultBytes.value=blob.size;return blob}async function download(){const blob=await getBlob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=cleanTopic.value+'.pptx';a.click();URL.revokeObjectURL(url)}async function preview(){const blob=await getBlob(),url=URL.createObjectURL(blob);window.open(url,'_blank');setTimeout(()=>URL.revokeObjectURL(url),60000)}
function enhancementStorageKey(){return `dokiai:ppt-enhancement:${project.value.id||'none'}`}function resetEnhancement(){enhancementPolling.value++;enhancementQuote.value={};enhancementTask.value={status:'IDLE',progress:0};enhancementBusy.value=false}function rememberEnhancementTask(task){if(project.value.id&&task?.id)localStorage.setItem(enhancementStorageKey(),String(task.id))}function createIdempotencyKey(){return globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`}
async function loadEnhancementState(){if(!project.value.id||stage.value!=='done')return;try{enhancementQuote.value=await getPptEnhancementQuote(project.value.id);let task=enhancementQuote.value.latestTask||null;if(!task){const localTaskId=localStorage.getItem(enhancementStorageKey());if(localTaskId){try{const localTask=await getPptEnhancementTask(project.value.id,localTaskId);if(localTask?.baseGenerationTaskId===enhancementQuote.value.baseGenerationTaskId)task=localTask;else localStorage.removeItem(enhancementStorageKey())}catch{localStorage.removeItem(enhancementStorageKey())}}}if(task){enhancementTask.value=task;rememberEnhancementTask(task);if(enhancementRunning.value)void pollEnhancement(task.id)}}catch(e){if(!String(e?.responseData?.code||'').includes('NOT_FOUND'))console.warn('[PPT enhancement state]',e)}}
function showEnhancementPointShortage(){const currentPoints=Number(enhancementQuote.value.currentPoints||0),requiredPoints=enhancementCost.value;window.dispatchEvent(new CustomEvent('dropai:points-not-enough',{detail:{currentPoints,requiredPoints,missingPoints:Math.max(0,requiredPoints-currentPoints),message:`PPT增幅美化需要 ${requiredPoints} 积分，当前剩余 ${currentPoints} 积分。`}}))}
async function confirmEnhancement(){if(enhancementBusy.value)return;enhancementBusy.value=true;try{enhancementQuote.value=await getPptEnhancementQuote(project.value.id);if(enhancementQuote.value.enabled===false){ElMessage.warning('PPT 增幅美化功能当前未启用');return}if(enhancementQuote.value.providerConfigured===false){ElMessage.warning('豆包增幅服务尚未配置');return}if(enhancementQuote.value.canStart===false){showEnhancementPointShortage();return}const cost=Number(enhancementQuote.value.costPoints||0),balance=enhancementQuote.value.currentPoints;await ElMessageBox.confirm(`将在基础版 PPT 生成完成后调用增幅美化 Skill。本次费用为基础生成积分的 50%，共 ${cost} 积分；仅在增强版通过校验后扣除，失败不扣积分。${balance==null?'':` 当前余额 ${balance} 积分。`}`,'确认启动增幅美化',{confirmButtonText:`确认并消耗 ${cost} 积分`,cancelButtonText:'暂不增强',type:'info',customClass:'ppt-enhancement-confirm'});const task=await startPptEnhancement(project.value.id,{baseGenerationTaskId:enhancementQuote.value.baseGenerationTaskId,idempotencyKey:createIdempotencyKey(),profile:'balanced'});enhancementTask.value=task;rememberEnhancementTask(task);ElMessage.success('增幅美化任务已启动，基础版 PPT 可继续下载');if(enhancementRunning.value)void pollEnhancement(task.id)}catch(e){if(e!=='cancel'&&e!=='close'&&e?.message!=='cancel')console.warn('[PPT enhancement start]',e)}finally{enhancementBusy.value=false}}
async function pollEnhancement(taskId){const pollToken=++enhancementPolling.value;for(let attempt=0;attempt<900&&componentAlive.value&&pollToken===enhancementPolling.value;attempt++){try{const task=await getPptEnhancementTask(project.value.id,taskId);enhancementTask.value=task;rememberEnhancementTask(task);if(String(task.status).toUpperCase()==='SUCCESS'){ElMessage.success('精美增强版 PPT 已生成');return}if(String(task.status).toUpperCase()==='FAILED')return}catch(e){console.warn('[PPT enhancement poll]',e);return}await new Promise(resolve=>setTimeout(resolve,1500))}}
async function getEnhancementBlob(){if(!enhancementDownloadable.value)throw new Error('增强文件尚未通过下载校验');const taskId=enhancementTask.value.id;if(!taskId)throw new Error('增强任务不存在');const blob=await downloadPptEnhancement(project.value.id,taskId);enhancementTask.value={...enhancementTask.value,fileSize:blob.size};return blob}async function downloadEnhancementFile(){const blob=await getEnhancementBlob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${cleanTopic.value}_精美增强版.pptx`;a.click();URL.revokeObjectURL(url)}async function previewEnhancement(){const blob=await getEnhancementBlob(),url=URL.createObjectURL(blob);window.open(url,'_blank');setTimeout(()=>URL.revokeObjectURL(url),60000)}
function reset(){stage.value='upload';project.value={progress:0};analysis.value={};outline.value=[];pages.value=[];logs.value=[];activeStep.value=0;file.value=null;generatedSlideCount.value=0;resultBytes.value=0;resetEnhancement()}function resume(){return resumeCurrentProject()}
onMounted(async()=>{await loadTemplates();if(!route.query.projectId)return;try{const data=await getPptProject(route.query.projectId);project.value=data;applyBaseGenerationResult(data);outline.value=data.outline||[];pages.value=data.slides||[];analysis.value=JSON.parse(data.analysis_json||'{}');const saved=data.templatePackId||data.template_id||data.templateId||data.template_style;if(['academic-purple','small-bear-watercolor-blue-v1'].includes(saved))selectedTemplateId.value=saved;stage.value=data.status==='SUCCESS'?'done':data.status==='FAILED'?'error':data.status==='DRAFT'?'upload':'running';activeStep.value=data.status==='SUCCESS'?5:Math.min(5,Math.floor(Number(data.progress||0)/17));if(stage.value==='done'){const progress=await getPptProgress(project.value.id);project.value={...project.value,...progress};pages.value=progress.slides||pages.value;applyBaseGenerationResult(progress);await loadEnhancementState()}if(['UPLOADED','ANALYZED','OUTLINE_READY','PLANNED','GENERATING'].includes(String(data.status||'')))void resumeCurrentProject()}catch(e){ElMessage.warning('项目无法恢复')}});onBeforeUnmount(()=>{componentAlive.value=false;enhancementPolling.value++});
